func init() {
	// the meter provider is intentionally a no-op by default.
	// the real exporter (and therefore the meter provider which uses it) is
	// constructed lazily via GetExporter, which is driven by configuration.
	// this avoids registering prometheus collectors during package initialization
	// which would otherwise make it impossible to configure an exporter later.
	provider := noopmetric.NewMeterProvider()
	otel.SetMeterProvider(provider)

	// instruments are built from the global meter provider so that they are
	// transparently re-bound when the real provider is configured at startup.
	Meter = otel.Meter("github.com/flipt-io/flipt")
}

// GetExporter builds the metrics exporter and returns the SDK reader which
// consumes it, along with a function for shutting the exporter down.
// The exporter is only constructed once, the first time this is called, which
// is why the underlying sync.Once is package scoped.
func GetExporter(ctx context.Context, cfg *config.MetricsConfig) (sdkmetric.Reader, func(context.Context) error, error) {
	var (
		reader   sdkmetric.Reader
		shutdown func(context.Context) error
		err      error
	)

	metricExpOnce.Do(func() {
		switch cfg.Exporter {
		case config.MetricsPrometheus:
			var exp *prometheus.Exporter
			exp, err = prometheus.New()
			if err != nil {
				err = fmt.Errorf("creating prometheus exporter: %w", err)
				return
			}

			reader = exp
			shutdown = func(context.Context) error { return nil }
		case config.MetricsOTLP:
			reader, shutdown, err = otlpExporter(ctx, cfg)
		default:
			err = fmt.Errorf("unsupported metrics exporter: %s", cfg.Exporter)
		}
	})

